def merge(intervals):
    if not intervals:
        return []
    ordered = sorted(intervals)
    out = [(ordered[0][0], ordered[0][1])]
    for start, end in ordered[1:]:
        last_start, last_end = out[-1]
        if start <= last_end:
            out[-1] = (last_start, max(last_end, end))
        else:
            out.append((start, end))
    return out
